import math
from functools import reduce

def gcd(a, b):
    while b:
        a, b = b, a % b
    return a

def lcm(a, b):
    if a == 0 or b == 0:
        return 0
    return abs(a * b) // gcd(a, b)

def list_gcd(numbers):
    if not numbers:
        return 0
    return reduce(gcd, numbers)

def list_lcm(numbers):
    if not numbers:
        return 1
    return reduce(lcm, numbers)

def count_good_partitions(sequence):
    n = len(sequence)
    if n < 2:
        return 0

    good_partitions = 0

    # Check k from 1 to n-1
    for k in range(1, n):
        A_k = sequence[:k]
        B_k = sequence[k:]

        lcm_A = list_lcm(A_k)
        gcd_B = list_gcd(B_k)

        if lcm_A == gcd_B:
            good_partitions += 1

    return good_partitions

# Test case for n=5: Sequence (1, 2, 4, 5, 20)
sequence_n5 = [1, 2, 4, 5, 20]
n5_count = count_good_partitions(sequence_n5)
print(f"N_good(5) for {sequence_n5}: {n5_count}")

# Test case for n=4: Sequence (1, 2, 3, 6)
sequence_n4 = [1, 2, 3, 6]
n4_count = count_good_partitions(sequence_n4)
print(f"N_good(4) for {sequence_n4}: {n4_count}")
